using System.Collections.Generic;public class LRUCache{int cap;LinkedList<(int k,int v)>q=new();Dictionary<int,LinkedListNode<(int k,int v)>>m=new();public LRUCache(int capacity){cap=capacity;}public int Get(int k){if(!m.TryGetValue(k,out var n))return-1;q.Remove(n);q.AddFirst(n);return n.Value.v;}public void Put(int k,int v){if(m.TryGetValue(k,out var n)){n.Value=(k,v);q.Remove(n);q.AddFirst(n);return;}if(m.Count==cap){var last=q.Last;m.Remove(last.Value.k);q.RemoveLast();}var x=new LinkedListNode<(int,int)>((k,v));q.AddFirst(x);m[k]=x;}}
